{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "실행 계획에서 찾은 병목이 인덱스 추가와 조인 정리라는 개선 방법의 선택으로 이어졌는지 확인한다. 개선 방법을 선택한 근거가 실제 조회 구조와 측정 결과로 뒷받침되는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 3.2초 걸렸다.",
          "task": "신고 목록 조회 쿼리에 인덱스를 추가하고 조인을 정리해 조회 시간을 0.4초로 줄였다.",
          "action": "실행 계획에서 확인한 전체 조인과 조회 조건을 근거로 인덱스 추가와 조인 정리를 선택한 이유를 설명한다.",
          "result": "3.2초에서 0.4초로 줄어든 측정 결과가 선택한 개선 방법의 타당성을 어떻게 뒷받침하는지 설명한다."
        },
        "expectedEvidence": [
          "인덱스 추가와 조인 정리를 선택한 구체적인 근거",
          "실행 계획에서 확인한 신고 테이블과 판매글 테이블의 조인 및 조회 조건",
          "선택한 개선 방법의 효과를 뒷받침하는 개선 전후 조회 시간"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄이셨을 때, 실행 계획을 보고 인덱스 추가와 조인 정리를 선택한 근거는 무엇이었나요?",
      "answerTip": "핵심부터 말하고 설명을 덧붙여 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 조인이나 조회 조건의 문제를 선택한 개선 방법과 구체적으로 연결한다.",
            "인덱스 추가와 조인 정리가 해당 병목을 줄이는 이유를 실제 조회 구조나 전후 측정 결과로 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실행 계획을 근거로 인덱스 추가와 조인 정리를 선택했다고 답하지만 확인한 문제의 설명이 포괄적이다.",
            "개선 방법과 속도 향상의 관련성은 설명하지만 해당 쿼리에 그 방법이 적합했던 근거가 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스를 추가하면 빨라진다는 일반론만 말하고 실행 계획에서 확인한 문제와 연결하지 못한다.",
            "수행한 조치나 최종 조회 시간만 반복하고 개선 방법을 선택한 근거는 제시하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 좁힌 장애 원인이 같은 장애를 막는 조치로 이어졌는지 확인한다. 당장의 잠금 적용을 넘어 배포 체크리스트에 스케줄러 항목을 넣은 근거가 로그에서 확인한 원인과 연결되는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 간다는 문의가 들어왔다.",
          "task": "로그를 시간순으로 모아 두 서버에서 스케줄러가 동시에 실행되는 원인을 찾고 잠금을 적용했으며 배포 체크리스트에 스케줄러 항목을 넣었다.",
          "action": "시간순 로그에서 확인한 두 서버의 스케줄러 동시 실행이 배포 체크리스트에 스케줄러 항목을 넣는 근거가 된 이유를 설명한다.",
          "result": "추가한 체크리스트 항목이 같은 중복 실행의 재발 가능성을 줄이는 이유를 설명하되 실제 재발 여부는 확인된 범위에서만 말한다."
        },
        "expectedEvidence": [
          "로그 추적 결과를 배포 체크리스트의 스케줄러 항목에 반영한 근거",
          "시간순 로그에서 확인한 두 서버의 스케줄러 동시 실행",
          "확인한 장애 원인과 체크리스트 항목 사이의 연결"
        ]
      },
      "question": "포켓마켓에서 알림 중복 발송 오류를 고치셨을 때, 로그 추적 결과를 배포 체크리스트의 스케줄러 항목에 반영한 근거는 무엇이었나요?",
      "answerTip": "핵심부터 말하고 설명을 덧붙여 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "시간순 로그에서 확인한 두 서버의 스케줄러 동시 실행을 체크리스트 항목 추가의 구체적인 근거로 제시한다.",
            "스케줄러 항목을 배포 때 확인하는 것이 확인된 장애 원인의 반복을 막는 데 어떤 관련이 있는지 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "로그로 스케줄러 중복 실행을 확인해 체크리스트에 반영했다고 답하지만 로그와 항목의 연결이 구체적이지 않다.",
            "동일 장애를 예방하려는 취지는 설명하지만 스케줄러 항목이 해당 원인에 대응하는 이유는 일부만 설명한다."
          ]
        },
        "poor": {
          "criteria": [
            "배포 체크리스트가 중요하다는 일반론만 말하고 로그에서 확인한 원인과 연결하지 못한다.",
            "잠금을 적용했다는 조치만 반복하거나 클라이언트 문제를 추측하며 체크리스트에 반영한 근거를 제시하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "흩어진 요청의 목적과 범위를 정리해 구현할 요구사항으로 구체화할 수 있는지 확인한다. 요구사항 정의서를 작성하며 개발 담당 팀원과 범위를 조정한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "플랜업스쿨 서비스 기획 과정의 동네 세탁소 예약 서비스 기획 프로젝트에서 세탁소 5곳을 인터뷰했다.",
          "task": "기획 담당으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "인터뷰에서 파악한 요청의 목적과 서비스 범위를 연결해 범위 조정의 근거를 설명한다.",
          "result": "제시한 근거가 개발 담당 팀원과 정한 요구사항 범위에 어떻게 반영됐는지 설명한다."
        },
        "expectedEvidence": [
          "개발 담당 팀원과 요구사항 범위를 조정한 판단 근거",
          "그 판단을 뒷받침한 세탁소 인터뷰의 요청과 목적",
          "제시한 근거와 조정한 요구사항 범위의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 요구사항 정의서를 작성하셨을 때, 개발 담당 팀원과 범위를 조정한 근거는 무엇이었나요?",
      "answerTip": "구체적인 사례 하나로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "범위를 조정한 근거를 실제 요청의 목적과 연결해 구체적으로 설명한다.",
            "어떤 요청을 이번 범위에 포함하거나 제외할지에 관한 판단이 제시한 근거와 일관된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "범위를 조정한 근거를 설명하지만 요청의 목적과 연결하는 내용이 일반적이다.",
            "포함하거나 제외할 범위에 관한 판단은 드러나지만 이를 뒷받침하는 정보가 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항 정의서를 작성했다는 사실만 반복하고 범위를 조정한 근거는 제시하지 못한다.",
            "협업의 중요성이나 문서 작성 도구만 설명해 요구사항 범위 판단을 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "기능 흐름에서 생길 예외를 화면의 상태와 안내로 구체화할 수 있는지 확인한다. 화면설계서의 예외 상황을 어떤 근거로 설계했는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획 프로젝트에서 예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 Figma로 작성했다.",
          "task": "기획 담당으로 예약·취소·알림 흐름과 예외 상황을 화면설계서에 담았다.",
          "action": "예외 상황의 발생 조건과 사용자에게 필요한 화면 반응을 연결해 설계 판단의 근거를 설명한다.",
          "result": "설계 근거가 예외 상황의 화면 상태나 안내 문구에 어떻게 반영됐는지 설명한다."
        },
        "expectedEvidence": [
          "예약·취소·알림 흐름의 예외 상황을 설계한 판단 근거",
          "그 판단의 바탕이 된 예외 발생 조건과 사용자 상황",
          "제시한 근거와 화면 상태 또는 안내 문구의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨을 때, 예약·취소·알림 흐름의 예외 상황을 설계한 근거는 무엇이었나요?",
      "answerTip": "떠올린 장면을 짧게 설명해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 상황을 설계한 근거를 실제 기능 흐름의 발생 조건과 연결해 구체적으로 설명한다.",
            "제시한 근거가 화면 상태나 안내 문구에 반영된 판단과 일관되어 개발·디자인 담당자가 의도한 동작을 이해할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황을 설계한 근거를 제시하지만 발생 조건이나 사용자 상황에 대한 설명이 일반적이다.",
            "설계 근거와 화면 상태 또는 안내 문구의 연결은 드러나지만 구체적인 뒷받침이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 포함했다는 사실만 반복하고 설계 판단의 근거는 제시하지 못한다.",
            "화면의 미관이나 Figma 기능만 설명해 예외 상황에 대한 설계 판단을 확인할 수 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방 용량이 의심스러울 때 투약을 그대로 진행하지 않고 확인하는 판단을 검증한다. 평소와 다른 처방을 확인이 필요한 처방으로 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 근무 2년 차에 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어왔다.",
          "task": "수술 전후 환자의 투약·처치를 담당했다.",
          "action": "처방 용량을 의심한 정보와 투약을 멈추고 담당의에게 확인하기로 판단한 근거를 설명한다.",
          "result": "담당의 확인으로 입력 오류임을 확인한 결과가 당시 판단의 근거와 어떻게 연결되는지 설명한다."
        },
        "expectedEvidence": [
          "투약을 멈추고 담당의에게 확인하기로 판단한 근거",
          "처방 용량의 적절성을 의심할 때 비교하거나 확인한 정보",
          "처방 확인 전 투약을 진행할 수 없다고 본 이유"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배로 들어왔을 때, 투약을 멈추고 담당의에게 확인하기로 판단한 근거는 무엇이었나요?",
      "answerTip": "본인이 한 판단을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소 용량과 해당 처방의 차이 등 당시 확인한 정보를 들어 처방을 의심한 근거를 구체적으로 설명한다.",
            "용량 차이만으로 오류를 단정하지 않으면서도 확인 전에는 안전한 투약을 보장할 수 없어 중단했다는 판단을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소보다 용량이 많아 처방 확인이 필요했다고 답하지만 비교한 정보는 구체적이지 않다.",
            "의심스러운 처방은 투약 전에 확인해야 한다는 근거를 제시하지만 당시 상황과의 연결은 제한적이다."
          ]
        },
        "poor": {
          "criteria": [
            "입력 오류였다는 결과만 반복하고 당시 투약을 중단한 판단 근거는 설명하지 못한다.",
            "환자 안전이 중요하다는 일반론만 말하거나 의심스러운 처방도 확인 없이 수행해도 된다는 판단을 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "환자 상태와 관련된 정보를 다음 근무자에게 빠짐없이 전달할 정보로 판단할 수 있는지 검증한다. 사고 보고서에서 확인한 교대 시간대의 위험을 진통제 투여 시각의 인수인계 필요성과 연결한 근거에 초점을 둔다.",
        "questionType": "behavioral",
